async function run(wf, args) {
{
  const { tasks, batches } = args ?? {};

  const FIXED_RULES = `You are an isolated subagent implementing ONE task of an approved project. You have no
prior conversation context — your full brief is inlined in the '## Task to implement' block
below plus the rules here. Where the task is ambiguous, make a reasonable decision and record it.

- Your full brief — goal, context files, requirements with their allocated failing tests,
  conventions, and constraints — is ALREADY in your prompt. Treat the inlined brief as the
  source of truth, and re-read the task file only when a referenced file's details are missing.

- Work at the repo root (your cwd). Leave all changes UNCOMMITTED — a later review reads the diff.
- Work only on the files named in your task's \\\\\`owned_files\\\\\`. A file outside \\\\\`owned_files\\\\\`,
  including any \\\\\`forbidden_files\\\\\` another task owns, stays untouched — parallel agents may be
  working at the same time.
- Your requirement's failing property tests are already written (named in \\\\\`requirements[].test\\\\\`).
  FIRST prioritize STRENGTHENING / completing those existing failing test cases — extend the
  property, add the missing edge cases and invariant asserts — then make them GREEN. Start from
  the allocated failing test as the acceptance target and extend it, rather than writing a
  brand-new property test from scratch for a requirement that already has an allocated failing test.
- Follow the project's conventions (AGENTS.md / CLAUDE.md): run lint / typecheck / build, add
  tests for new behaviour, and make your requirements' failing property tests GREEN.
- Verify external APIs against real documentation before using them; write only what you have checked.
- Record any deviation from the design doc in \\\\\`deviations\\\\\`.
- Report your result with the \\\\\`structured_output\\\\\` tool exactly once: the JSON report
  (changed_files, satisfied_requirements, deviations). The \\\\\`structured_output\\\\\` call is the
  result; finish with it, and report the JSON in that call.`;

  const RETURN_SCHEMA = {
    type: 'object',
    required: ['changed_files', 'satisfied_requirements'],
    properties: {
      changed_files: { type: 'array', items: { type: 'object', required: ['file', 'lines'], properties: { file: { type: 'string' }, lines: { type: 'string' } } } },
      satisfied_requirements: { type: 'array', items: { type: 'string' } },
      deviations: { type: 'array', items: { type: 'string' } },
    },
  };

  // Build a SMALL per-task prompt by inlining the task brief from promptFile
  // (a repo-relative path) via wf.readFile, so run_workflow args stay tiny and
  // the subagent does NOT read the file itself. Falls back to "read it yourself"
  // if the inlined load fails (graceful degradation), and throws if a task is
  // missing promptFile (a contract violation).
  async function taskPrompt(t) {
    if (t == null || typeof t !== 'object') throw new Error('implement task must be an object');
    const id = t.id === undefined ? 'task' : String(t.id);
    if (typeof t.promptFile !== 'string' || t.promptFile.trim().length === 0) {
      throw new Error('implement task "' + id + '" is missing a promptFile path: write the task brief to a file and pass its repo-relative path (keep args small)');
    }
    let brief = '';
    try {
      brief = (await wf.readFile(t.promptFile)) || '';
    } catch {
      brief = '';
    }
    const briefBlock = brief.trim().length > 0
      ? brief.trim()
      : '! The task brief could not be loaded automatically — read the file at ' + t.promptFile + ' now with the read tool. It is your full brief (goal, owned/forbidden files, requirements + their allocated failing tests, conventions, constraints).';
    return [
      '## Task to implement',
      '- task id: ' + id,
      '- task name: ' + (t.name === undefined ? id : String(t.name)),
      '- task file: ' + t.promptFile,
      '',
      briefBlock,
    ].join('\n');
  }

  const groups = batches ?? (tasks ? [tasks] : []);
  const results = [];

  for (let b = 0; b < groups.length; b++) {
    const label = groups.length > 1 ? 'batch-' + (b + 1) : 'implement';
    const done = await wf.phase(label, () => wf.parallel(
      groups[b].map(t => async () => wf.runAgent({
        name: String(t?.id ?? 'task'),
        prompt: await taskPrompt(t) + '\n\n' + FIXED_RULES,
        readOnly: false,
        modelHint: 'balanced',
        outputSchema: RETURN_SCHEMA,
      })),
    ));
    if (done.some(r => r === null)) return { status: 'failed', batch: b + 1 };
    results.push(...done.map(r => r.structured));
  }
  return { status: 'done', agents: results.length };
}
}
